using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

Console.WriteLine("Research Agent Starting...");
Console.WriteLine("========================\n");

var topic = args.Length > 0 ? string.Join(' ', args) : "latest advances in quantum computing 2026";
Console.WriteLine($"Researching topic: {topic}\n");

// Configure the chat client with tool support
var endpoint = Environment.GetEnvironmentVariable("OPENAI_ENDPOINT") ?? "https://api.openai.com/v1";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");

var openAiClient = new OpenAI.OpenAIClient(apiKey);
IChatClient innerClient = openAiClient.GetChatClient(model).AsIChatClient();

// Register tools
var notes = new ResearchNotes();
var searchTool = new WebSearchTool();

IChatClient chatClient = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(searchTool.SearchWeb),
        AIFunctionFactory.Create(notes.AddNote),
        AIFunctionFactory.Create(notes.GetNotes),
    ]
};

var systemPrompt = """
    You are a research agent. Your job is to research a given topic thoroughly using the available tools.

    Your workflow:
    1. Search the web for relevant information about the topic (perform multiple searches with different queries).
    2. Take notes on key findings using the note-taking tool.
    3. Once you have gathered enough information, retrieve all your notes and produce a comprehensive summary.

    Always take notes on important findings before producing the final summary.
    When you are done researching, provide a final structured summary with sections and key points.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

Console.WriteLine("Agent is researching (this may take a moment)...\n");

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("===== RESEARCH SUMMARY =====\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n===== NOTES COLLECTED =====\n");
foreach (var note in notes.AllNotes)
{
    Console.WriteLine($"• {note}");
}

// --- Tool Definitions ---

/// <summary>Tool that searches the web for information on a query.</summary>
public sealed class WebSearchTool
{
    private static readonly HttpClient Http = new();

    [Description("Searches the web for information. Returns a list of result snippets for the given query.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        // Use DuckDuckGo Instant Answer API (no key required)
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var result = await Http.GetFromJsonAsync<JsonElement>(url);

            var snippets = new List<string>();

            if (result.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
                snippets.Add($"Summary: {abstractText}");

            if (result.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                        snippets.Add(t);
                }
            }

            if (snippets.Count == 0)
                snippets.Add($"No detailed results found for '{query}'. Try a different search query.");

            return string.Join("\n\n", snippets);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>Tool for collecting research notes during investigation.</summary>
public sealed class ResearchNotes
{
    private readonly List<string> _notes = new();

    public IReadOnlyList<string> AllNotes => _notes;

    [Description("Adds a research note. Use this to record key findings during research.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note added ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

